function v5TrCore(core,k,dep){const d=V5I18N[core];if(d)return d[k];if(dep>2)return null;
 for(const [re,en,es] of V5I18NP){const x=core.match(re);if(x){let o=k?es:en;return o.replace(/\$(\d)/g,(_,i)=>{const v=x[+i]||'';const r=v5TrCore(v,k,dep+1);return r!=null?r:v})}}return null}
function v5Tr(t){const L=v5Lang();if(!L||L==='pt')return null;const k=L==='en'?0:1;const m=t.match(/^(\s*)([\s\S]*?)(\s*)$/),core=m[2];if(!core)return null;const r=v5TrCore(core,k,0);return r==null?null:m[1]+r+m[3]}
const V5TRSKIP={SCRIPT:1,STYLE:1,TEXTAREA:1,svg:1,CANVAS:1,CODE:1};
function v5TrNode(n){if(n.nodeType===3){const p=n.parentNode;if(!p||V5TRSKIP[p.nodeName]||p.isContentEditable||p.closest&&p.closest('.v5noi18n'))return;const t=n.nodeValue;if(!/[A-Za-zÀ-ú]/.test(t))return;const r=v5Tr(t);if(r!=null&&r!==t)n.nodeValue=r;return}
 if(n.nodeType!==1||V5TRSKIP[n.nodeName])return;
 for(const a of ['placeholder','aria-label','title'])if(n.hasAttribute&&n.hasAttribute(a)){const r=v5Tr(n.getAttribute(a));if(r!=null)n.setAttribute(a,r)}
 const w=document.createTreeWalker(n,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);let x;const L=[];while(x=w.nextNode())L.push(x);for(const y of L){if(y.nodeType===3)v5TrNode(y);else for(const a of ['placeholder','aria-label','title'])if(y.hasAttribute(a)){const r=v5Tr(y.getAttribute(a));if(r!=null)y.setAttribute(a,r)}}}
(function(){try{let busy=false;const mo=new MutationObserver(ms=>{if(busy||!v5Lang()||v5Lang()==='pt')return;busy=true;try{for(const m of ms){if(m.type==='characterData')v5TrNode(m.target);else m.addedNodes.forEach(v5TrNode)}}finally{busy=false}});
 const go=()=>{mo.observe(document.body,{childList:true,subtree:true,characterData:true});if(v5Lang()&&v5Lang()!=='pt')v5TrNode(document.body);document.documentElement.lang={en:'en',es:'es'}[v5Lang()]||'pt-BR'};document.body?go():document.addEventListener('DOMContentLoaded',go)}catch(e){}})();
